import { isTauri } from "@tauri-apps/api/core";
import { ChevronDown } from "lucide-react";
import { useEffect, useState } from "react";
import { useTranslation } from "react-i18next";
import { commands, type Notices } from "@/shared/ipc/bindings";
import { cn } from "@/shared/lib/utils";
import { Dialog } from "@/shared/ui/Dialog";

/**
 * «Лицензии» (T6.6, NFR-LIC-001): what is inside Сиртон and under which terms — the font,
 * models, data, presets and services first, then every package grouped by its license text.
 * The texts are data (generated by `tools/notices.py`), opened one by one.
 */
export function LicensesDialog({ onClose }: { onClose: () => void }) {
  const { t } = useTranslation("shell");
  const { t: tc } = useTranslation("common");
  const [n, setN] = useState<Notices | null>(null);
  const [open, setOpen] = useState<number | null>(null);
  useEffect(() => {
    if (isTauri()) void commands.legalNotices().then(setN);
  }, []);
  return (
    <Dialog title={t("licenses.title")} closeLabel={tc("errors.close")} onClose={onClose} wide>
      <div className="flex max-h-[65vh] flex-col gap-2 overflow-auto pr-1" data-testid="licenses">
        {n && (
          <p className="t-caption text-text-secondary">
            {t("licenses.summary", { rust: n.rust, js: n.js })}
          </p>
        )}
        {n?.sections.map((s, i) => (
          <div key={`${s.title}-${s.items[0] ?? ""}`} className="rounded-(--radius-md) bg-bg-layer">
            <button
              type="button"
              aria-expanded={open === i}
              onClick={() => setOpen(open === i ? null : i)}
              className="flex w-full items-start gap-3 px-4 py-3 text-left"
            >
              <span className="min-w-0 flex-1">
                <span className="t-body-strong block text-text-primary">
                  {s.items.length > 0 ? s.license : s.title}
                </span>
                <span className="t-caption block text-text-secondary">
                  {s.items.length > 0 ? s.items.join(", ") : s.license}
                </span>
              </span>
              <ChevronDown
                size={16}
                strokeWidth={1.5}
                className={cn("mt-1 shrink-0 text-icon", open === i && "rotate-180")}
              />
            </button>
            {open === i && (
              <pre className="t-caption m-0 overflow-auto px-4 pb-4 whitespace-pre-wrap text-text-secondary">
                {s.text}
              </pre>
            )}
          </div>
        ))}
      </div>
    </Dialog>
  );
}
